import type {Snapshot,FileSourceRef} from './progress-model.ts';
/** Additive transport contract. Preserve authoritative domain IDs and source records. */
export interface NativeIdentity {state:'known'|'unknown'|'not_applicable';id:string|null;system:string|null;sourceRefs:string[]}
export interface StableEntity {id:string;revision:number;native:NativeIdentity;sourceRefs:string[]}
export interface EditionBinding extends StableEntity {bookCode:string;edition:number|string;bookCacheRef:string}
export interface UnitBinding extends StableEntity {editionRef:string;tocNodeRef:string;bindingState:'verified'|'candidate'|'unresolved'}
export interface SectionBinding extends StableEntity {unitRef:string;legacyRecordRefs:string[];sourceSectionId:string|null;sourceLabel:string;displayOrder:number|null;existenceState:'observed'|'verification_slot'|'unknown';bindingState:'verified'|'candidate'|'unresolved'}
export interface Item extends StableEntity {sectionRef:string;printedPage:string|null;questionLabel:string|null;partLabel:string|null;mappingState:'verified'|'candidate'|'unresolved';contentEvidenceRefs:string[]}
export interface ItemVariant extends StableEntity {itemRef:string;kind:'source'|'similar'|'revised'|'reprint';contentEvidenceRefs:string[];supersedesVariantRefs:string[]}
export interface ItemAttempt extends StableEntity {studentRef:string;sourceAttemptId:string|null;itemRef:string;variantRef:string;assignmentInstanceRef:string|null;occurredAt:string|null;effectiveAt:string|null;observedAt:string|null;recordedAt:string|null;rawDate:string|null;yearState:'known'|'unknown';timezoneState:'known'|'unknown';retryOfAttemptRef:string|null;remediatesAttemptRef:string|null;answerEvidenceRefs:string[]}
export interface ItemGrade extends StableEntity {attemptRef:string;actor:'auto'|'teacher'|'unknown';state:'not_graded'|'graded'|'partial'|'unavailable';score:{earned:number;possible:number;unit:string}|null;correctness:'correct'|'incorrect'|'partial'|'unknown'|'not_applicable';effectiveAt:string|null;supersedesGradeRefs:string[]}
export interface ItemReview extends StableEntity {attemptRef:string;gradeRef:string|null;verdict:'confirmed_complete'|'confirmed_incomplete'|'needs_check'|'unknown'|'disputed';effectiveAt:string|null;supersedesReviewRefs:string[]}
export interface EvidenceTarget {unitRefs:string[];sectionRefs:string[];itemRefs:string[];attemptRefs:string[];notebookRefs:string[]}
export interface ItemEvidence extends StableEntity {kind:'source_record'|'answer_image'|'lecture_note_capture'|'solution_note_capture'|'grading_annotation';studentRef:string|null;editionRef:string;fileSourceRef:string;capturedAt:string|null;originalPointer:string;targets:EvidenceTarget}
export interface ItemNotebook extends StableEntity {studentRef:string;editionRef:string;kind:'lecture_notes'|'solution_notes';captureState:'captured'|'not_captured'|'capture_partial'|'unavailable';targets:EvidenceTarget;evidenceRefs:string[];reviewRefs:string[];openQuestions:{id:string;text:string;itemRef:string|null;state:'open'|'resolved';sourceRefs:string[]}[]}
export interface QuestionLayer {schemaVersion:'1.0.0';state:'not_captured'|'partial'|'verified_in_scope'|'unavailable';studentRef:string|null;sources:FileSourceRef[];editions:EditionBinding[];units:UnitBinding[];sections:SectionBinding[];items:Item[];variants:ItemVariant[];attempts:ItemAttempt[];grades:ItemGrade[];reviews:ItemReview[];evidence:ItemEvidence[];notebooks:ItemNotebook[];coverage:{axis:'item';totalItems:number|null;totalEvidenceRefs:string[];assignmentClosed:boolean;requiredItemRefs:string[];completionCriteriaRef:string|null};migration:{fromSnapshotContract:string;policy:'additive_preserve_legacy';legacyIdsRekeyed:false}}
export interface QuestionValidation {valid:boolean;errors:string[];counts:Record<string,number>}
const object=(v:unknown):v is Record<string,unknown>=>typeof v==='object'&&v!==null&&!Array.isArray(v);
const list=(v:unknown):v is unknown[]=>Array.isArray(v);
const str=(v:unknown):v is string=>typeof v==='string'&&v.length>0;
const nullableString=(v:unknown)=>v===null||typeof v==='string';
const collections=['editions','units','sections','items','variants','attempts','grades','reviews','evidence','notebooks'] as const;
/** An empty layer declares no question facts or IDs. Do not manufacture bindings. */
export function emptyQuestionLayer(fromSnapshotContract:string,studentRef:string|null=null):QuestionLayer{return {schemaVersion:'1.0.0',state:'not_captured',studentRef,sources:[],editions:[],units:[],sections:[],items:[],variants:[],attempts:[],grades:[],reviews:[],evidence:[],notebooks:[],coverage:{axis:'item',totalItems:null,totalEvidenceRefs:[],assignmentClosed:false,requiredItemRefs:[],completionCriteriaRef:null},migration:{fromSnapshotContract,policy:'additive_preserve_legacy',legacyIdsRekeyed:false}};}
export function validateQuestionLayer(value:unknown,snapshot:Snapshot):QuestionValidation {
 const errors:string[]=[],counts:Record<string,number>={};const fail=(m:string)=>errors.push(m);
 if(!object(value))return {valid:false,errors:['questionLayer must be an object'],counts};
 if(value.schemaVersion!=='1.0.0')fail('Unsupported questionLayer schemaVersion');
 if(!['not_captured','partial','verified_in_scope','unavailable'].includes(String(value.state)))fail('Invalid questionLayer collection state');
 if(!nullableString(value.studentRef))fail('questionLayer nullable stable studentRef required');
 if(typeof snapshot.studentRef==='string'&&value.studentRef!==snapshot.studentRef)fail('questionLayer crosses selected student scope');
 const maps:Record<string,Map<string,Record<string,unknown>>>={};const allIds=new Set<string>();
 for(const key of collections){maps[key]=new Map();if(!list(value[key])){fail(`questionLayer ${key} must be an array`);continue;}counts[key]=value[key].length;for(const e of value[key]){
  if(!object(e)){fail(`${key} entity must be an object`);continue;}const id=String(e.id??'missing');
  if(!str(e.id)||!e.id.includes(':'))fail(`${key} requires opaque stable ID separate from native identity`);else{if(allIds.has(e.id))fail(`Duplicate stable ID ${e.id}`);allIds.add(e.id);maps[key].set(e.id,e);}
  if(!Number.isInteger(e.revision)||Number(e.revision)<1)fail(`${id} positive revision required`);
  if(!list(e.sourceRefs)||e.sourceRefs.length===0||e.sourceRefs.some(r=>!str(r)))fail(`${id} sourceRefs required`);
  const native=e.native;if(!object(native))fail(`${id} native identity status required`);else{if(!['known','unknown','not_applicable'].includes(String(native.state)))fail(`${id} native identity state invalid`);if(!nullableString(native.id)||!nullableString(native.system)||!list(native.sourceRefs)||native.sourceRefs.some(r=>!str(r)))fail(`${id} native identity fields invalid`);if(native.state==='known'&&(!str(native.id)||!str(native.system)||!list(native.sourceRefs)||native.sourceRefs.length===0))fail(`${id} known native identity needs ID, system, and evidence`);if(native.state!=='known'&&native.id!==null)fail(`${id} unknown/inapplicable native ID must stay null`);}
 }}
 const sources=new Map<string,Record<string,unknown>>();if(!list(value.sources))fail('questionLayer sources must be an array');else for(const s of value.sources){if(!object(s)||!str(s.sourceId)){fail('Question source identity required');continue;}if(sources.has(s.sourceId))fail(`Duplicate source ID ${s.sourceId}`);sources.set(s.sourceId,s);for(const k of ['version','locator','scope'])if(!str(s[k]))fail(`${s.sourceId} source ${k} required`);if(typeof s.sha256!=='string'||!/^[a-f0-9]{64}$/.test(s.sha256)||s.hashBasis!=='exact_file_bytes')fail(`${s.sourceId} exact source-byte hash required`);if(!nullableString(s.observedAt))fail(`${s.sourceId} nullable observation time required`);if(!['synthetic','private_student','public_book'].includes(String(s.dataClass)))fail(`${s.sourceId} data class invalid`);}
 const refs=(refs:unknown,map:Map<string,unknown>,label:string)=>{if(!list(refs)){fail(`${label} must be refs array`);return;}for(const ref of refs)if(!str(ref)||!map.has(ref))fail(`${label} unresolved ref ${String(ref)}`);};
 const need=(ref:unknown,key:string,label:string)=>{if(!str(ref)||!maps[key].has(ref)){fail(`${label} missing ${key} target ${String(ref)}`);return undefined;}return maps[key].get(ref);};
 const nullableRef=(ref:unknown,key:string,label:string)=>ref===null?undefined:need(ref,key,label);
 for(const key of collections)for(const e of maps[key].values()){refs(e.sourceRefs,sources,`${e.id} provenance`);if(object(e.native))refs(e.native.sourceRefs,sources,`${e.id} native provenance`);}
 const toc=new Map<string,{book:Record<string,unknown>;node:Record<string,unknown>}>();for(const b of snapshot.books??[]){const walk=(n:any)=>{if(object(n)&&str(n.id)){toc.set(n.id,{book:b,node:n});if(list(n.children))n.children.forEach(walk);}};b.units?.forEach(walk);}
 const legacy=new Map((snapshot.records??[]).map(r=>[r.recordId,r]));
 for(const e of maps.editions.values())if(!snapshot.books.some(b=>b.bookCode===e.bookCode&&b.edition===e.edition&&b.sharedBookCacheRef===e.bookCacheRef))fail(`${e.id} unselected edition/cache binding`);
 for(const u of maps.units.values()){const ed=need(u.editionRef,'editions',String(u.id)),node=toc.get(String(u.tocNodeRef));if(!node||!ed||node.book.bookCode!==ed.bookCode||node.book.edition!==ed.edition||node.book.sharedBookCacheRef!==ed.bookCacheRef)fail(`${u.id} exact selected TOC binding required`);if(!['verified','candidate','unresolved'].includes(String(u.bindingState)))fail(`${u.id} unit binding state invalid`);}
 for(const s of maps.sections.values()){const u=need(s.unitRef,'units',String(s.id));refs(s.legacyRecordRefs,legacy,`${s.id} legacy record refs`);if(list(s.legacyRecordRefs))for(const r of s.legacyRecordRefs){const record=legacy.get(String(r));if(record&&u&&record.tocNodeRef!==u.tocNodeRef)fail(`${s.id} legacy record crosses unit`);}if(!nullableString(s.sourceSectionId))fail(`${s.id} nullable sourceSectionId required`);if(!str(s.sourceLabel)||!(s.displayOrder===null||Number.isInteger(s.displayOrder)))fail(`${s.id} original label and nullable order required`);if(!['observed','verification_slot','unknown'].includes(String(s.existenceState))||!['verified','candidate','unresolved'].includes(String(s.bindingState)))fail(`${s.id} section axes invalid`);}
 const editionFor=(key:string,id:unknown):string|undefined=>{const e=maps[key]?.get(String(id));if(!e)return undefined;if(key==='editions')return String(e.id);if(key==='units'||key==='evidence'||key==='notebooks')return str(e.editionRef)?e.editionRef:undefined;if(key==='sections')return editionFor('units',e.unitRef);if(key==='items')return editionFor('sections',e.sectionRef);if(key==='variants'||key==='attempts')return editionFor('items',e.itemRef);if(key==='grades'||key==='reviews')return editionFor('attempts',e.attemptRef);return undefined;};
 for(const i of maps.items.values()){const section=need(i.sectionRef,'sections',String(i.id));for(const k of ['printedPage','questionLabel','partLabel'])if(!nullableString(i[k]))fail(`${i.id} nullable printed locator ${k} required`);if(!['verified','candidate','unresolved'].includes(String(i.mappingState)))fail(`${i.id} mappingState invalid`);if(i.mappingState==='verified'&&section?.existenceState!=='observed')fail(`${i.id} cannot verify an item under unverified section existence`);refs(i.contentEvidenceRefs,maps.evidence,`${i.id} content evidence`);}
 for(const v of maps.variants.values()){need(v.itemRef,'items',String(v.id));if(!['source','similar','revised','reprint'].includes(String(v.kind)))fail(`${v.id} variant kind invalid`);refs(v.contentEvidenceRefs,maps.evidence,`${v.id} content evidence`);refs(v.supersedesVariantRefs,maps.variants,`${v.id} supersession`);if(list(v.supersedesVariantRefs))for(const p of v.supersedesVariantRefs)if(maps.variants.get(String(p))?.itemRef!==v.itemRef)fail(`${v.id} variant supersession crosses item`);}
 for(const a of maps.attempts.values()){need(a.itemRef,'items',String(a.id));const v=need(a.variantRef,'variants',String(a.id));if(v&&v.itemRef!==a.itemRef)fail(`${a.id} variant/item mismatch`);if(!str(value.studentRef)||a.studentRef!==value.studentRef)fail(`${a.id} exact selected stable student required`);for(const k of ['sourceAttemptId','assignmentInstanceRef','occurredAt','effectiveAt','observedAt','recordedAt','rawDate'])if(!nullableString(a[k]))fail(`${a.id} nullable ${k} required`);if(!['known','unknown'].includes(String(a.yearState))||!['known','unknown'].includes(String(a.timezoneState)))fail(`${a.id} date uncertainty axes invalid`);if((a.yearState==='unknown'||a.timezoneState==='unknown')&&(a.occurredAt!==null||a.effectiveAt!==null))fail(`${a.id} unresolved event time must remain null`);for(const key of ['retryOfAttemptRef','remediatesAttemptRef']){const p=nullableRef(a[key],'attempts',String(a.id));if(p&&(p.studentRef!==a.studentRef||p.itemRef!==a.itemRef))fail(`${a.id} ${key} crosses student/item scope`);if(p&&key==='retryOfAttemptRef'&&(p.variantRef!==a.variantRef||p.assignmentInstanceRef!==a.assignmentInstanceRef))fail(`${a.id} retry must match variant/assignment scope`);}refs(a.answerEvidenceRefs,maps.evidence,`${a.id} answer evidence`);if(list(a.answerEvidenceRefs))for(const ref of a.answerEvidenceRefs){const e=maps.evidence.get(String(ref));if(e&&(!object(e.targets)||!list(e.targets.attemptRefs)||!e.targets.attemptRefs.includes(a.id)))fail(`${a.id} answer evidence must target this exact attempt`);}}
 for(const g of maps.grades.values()){need(g.attemptRef,'attempts',String(g.id));if(!['auto','teacher','unknown'].includes(String(g.actor))||!['not_graded','graded','partial','unavailable'].includes(String(g.state))||!['correct','incorrect','partial','unknown','not_applicable'].includes(String(g.correctness)))fail(`${g.id} grading axes invalid`);if(g.score!==null){if(!object(g.score)||typeof g.score.earned!=='number'||!Number.isFinite(g.score.earned)||typeof g.score.possible!=='number'||!Number.isFinite(g.score.possible)||g.score.possible<=0||g.score.earned<0||!str(g.score.unit))fail(`${g.id} score needs finite values, positive denominator, and unit`);}if(g.state==='not_graded'&&g.score!==null)fail(`${g.id} ungraded attempt cannot contain a score`);if(!nullableString(g.effectiveAt))fail(`${g.id} nullable grade time required`);refs(g.supersedesGradeRefs,maps.grades,`${g.id} grade supersession`);if(list(g.supersedesGradeRefs))for(const p of g.supersedesGradeRefs)if(maps.grades.get(String(p))?.attemptRef!==g.attemptRef)fail(`${g.id} grade supersession crosses attempt`);}
 for(const r of maps.reviews.values()){need(r.attemptRef,'attempts',String(r.id));const g=nullableRef(r.gradeRef,'grades',String(r.id));if(g&&g.attemptRef!==r.attemptRef)fail(`${r.id} review grade/attempt mismatch`);if(!['confirmed_complete','confirmed_incomplete','needs_check','unknown','disputed'].includes(String(r.verdict))||!nullableString(r.effectiveAt))fail(`${r.id} teacher review fields invalid`);refs(r.supersedesReviewRefs,maps.reviews,`${r.id} review supersession`);if(list(r.supersedesReviewRefs))for(const p of r.supersedesReviewRefs)if(maps.reviews.get(String(p))?.attemptRef!==r.attemptRef)fail(`${r.id} review supersession crosses attempt`);}
 const targets=(e:Record<string,unknown>,t:unknown)=>{if(!object(t)){fail(`${e.id} exact evidence targets required`);return;}for(const [field,key] of [['unitRefs','units'],['sectionRefs','sections'],['itemRefs','items'],['attemptRefs','attempts'],['notebookRefs','notebooks']] as const){refs(t[field],maps[key],`${e.id} ${field}`);if(list(t[field]))for(const ref of t[field]){if(editionFor(key,ref)!==e.editionRef)fail(`${e.id} target crosses edition`);const target=maps[key].get(String(ref));if(target&&'studentRef'in target&&target.studentRef!==e.studentRef)fail(`${e.id} target crosses student`);}}};
 for(const e of maps.evidence.values()){need(e.editionRef,'editions',String(e.id));if(!['source_record','answer_image','lecture_note_capture','solution_note_capture','grading_annotation'].includes(String(e.kind)))fail(`${e.id} evidence kind invalid`);if(!str(e.fileSourceRef)||!sources.has(e.fileSourceRef))fail(`${e.id} source snapshot missing`);if(e.studentRef!==null&&e.studentRef!==value.studentRef)fail(`${e.id} evidence crosses selected student`);if(['answer_image','lecture_note_capture','solution_note_capture','grading_annotation'].includes(String(e.kind))&&(!str(value.studentRef)||e.studentRef!==value.studentRef))fail(`${e.id} private answer/note evidence needs selected student scope`);if(!nullableString(e.capturedAt)||!str(e.originalPointer))fail(`${e.id} capture time and original locator required`);targets(e,e.targets);if(['answer_image','lecture_note_capture','solution_note_capture','grading_annotation'].includes(String(e.kind))&&sources.get(String(e.fileSourceRef))?.dataClass==='public_book')fail(`${e.id} private answer/note cannot use a public-book source classification`);}
 for(const n of maps.notebooks.values()){need(n.editionRef,'editions',String(n.id));if(!str(value.studentRef)||n.studentRef!==value.studentRef)fail(`${n.id} notebook crosses selected student`);if(!['lecture_notes','solution_notes'].includes(String(n.kind))||!['captured','not_captured','capture_partial','unavailable'].includes(String(n.captureState)))fail(`${n.id} notebook axes invalid`);targets(n,n.targets);refs(n.evidenceRefs,maps.evidence,`${n.id} notebook evidence`);refs(n.reviewRefs,maps.reviews,`${n.id} notebook review`);if(list(n.reviewRefs))for(const r of n.reviewRefs){const review=maps.reviews.get(String(r)),a=maps.attempts.get(String(review?.attemptRef));if(review&&(editionFor('reviews',r)!==n.editionRef||a?.studentRef!==n.studentRef))fail(`${n.id} notebook review crosses student/edition`);}if(list(n.evidenceRefs)&&((n.captureState==='not_captured'&&n.evidenceRefs.length>0)||(n.captureState==='captured'&&n.evidenceRefs.length===0)))fail(`${n.id} notebook capture state contradicts evidence`);if(!list(n.openQuestions))fail(`${n.id} openQuestions array required`);else for(const q of n.openQuestions){if(!object(q)||!str(q.id)||!str(q.text)||!['open','resolved'].includes(String(q.state)))fail(`${n.id} open question fields invalid`);else{nullableRef(q.itemRef,'items',String(q.id));refs(q.sourceRefs,sources,`${q.id} source refs`);}}}
 for(const [key,field] of [['variants','supersedesVariantRefs'],['attempts','retryOfAttemptRef'],['attempts','remediatesAttemptRef'],['grades','supersedesGradeRefs'],['reviews','supersedesReviewRefs']] as const){const visiting=new Set<string>(),done=new Set<string>();const visit=(id:string)=>{if(visiting.has(id)){fail(`${key} ${field} cycle at ${id}`);return;}if(done.has(id))return;visiting.add(id);const e=maps[key].get(id),next=e?.[field];for(const ref of list(next)?next:next===null?[]:[next])if(str(ref)&&maps[key].has(ref))visit(ref);visiting.delete(id);done.add(id);};for(const id of maps[key].keys())visit(id);}
 const c=value.coverage;if(!object(c)||c.axis!=='item')fail('Question coverage must use item axis');else{if(!(c.totalItems===null||Number.isInteger(c.totalItems)&&Number(c.totalItems)>=maps.items.size))fail('Question denominator must be null or a sourced integer not below observed items');refs(c.totalEvidenceRefs,sources,'Question total provenance');if(c.totalItems!==null&&(!list(c.totalEvidenceRefs)||!c.totalEvidenceRefs.length))fail('Known item denominator requires exact source provenance');if(typeof c.assignmentClosed!=='boolean')fail('Question assignment closure required');refs(c.requiredItemRefs,maps.items,'Required item refs');if(!nullableString(c.completionCriteriaRef))fail('Nullable completion criteria required');if(c.assignmentClosed&&(!str(c.completionCriteriaRef)||!sources.has(c.completionCriteriaRef)))fail('Closed assignment denominator needs sourced completion criteria');}
 const migration=value.migration;if(!object(migration)||migration.policy!=='additive_preserve_legacy'||migration.legacyIdsRekeyed!==false||migration.fromSnapshotContract!==snapshot.contractVersion)fail('Question migration must preserve exact legacy contract/IDs');
 if(value.state==='not_captured'){if(collections.some(k=>maps[k].size>0)||sources.size>0)fail('not_captured must not manufacture question-layer entities');if(object(c)&&(c.totalItems!==null||c.assignmentClosed!==false))fail('not_captured question coverage keeps denominator null and assignment open');}
 if(maps.items.size>0&&!str(value.studentRef))fail('Captured question layer requires explicit stable selected studentRef');
 return {valid:errors.length===0,errors,counts};
}
